// Golden regression tests against the Oct 7 reference workbook. Fixtures are
// generated by scripts/extract_golden.py, which fills Participant_IO with six
// scenario teams, recalculates the workbook, and records every Engine column.

import { describe, expect, it } from "vitest";
import golden from "./__fixtures__/oct7-golden.json";
import { defaultConfig } from "./defaultConfig";
import { computeRound, emptyDecisions, simulateTeam } from "./engine";
import type { Distribution, EvidenceTrigger, Intensity, RoundDecisions, RoundResult } from "./types";

const D = 9; // decimal places for float comparison

interface FixtureRound {
  initiatives: [string, Intensity][];
  posture: Distribution;
  workforce: "Yes" | "No";
  option: string;
  evidence: EvidenceTrigger;
  custom: null | ({ name: string } & Record<string, number | string>);
}

function toDecisions(r: FixtureRound): RoundDecisions {
  const d = emptyDecisions();
  r.initiatives.forEach(([name, intensity], i) => (d.initiatives[i] = { name, intensity }));
  d.distribution = r.posture;
  d.workforceReduction = r.workforce === "Yes";
  d.strategicOption = r.option;
  d.evidenceTriggerMet = r.evidence;
  if (r.custom) {
    const c = r.custom;
    d.customAction = {
      name: String(c.name),
      capital: Number(c.capital),
      lc: Number(c.lc),
      m: Number(c.m),
      v: Number(c.v),
      k: Number(c.k),
      f: Number(c.f),
      c: Number(c.c),
      ec: Number(c.ec),
      oc: Number(c.oc),
      marginPp: Number(c.marginPp),
      mixPp: Number(c.mixPp),
    };
  }
  return d;
}

const EFFECT = ["m", "v", "k", "f", "c", "ec", "oc", "marginPp", "mixPp"] as const;
const LOOPS = ["m", "v", "k", "f", "c", "ec", "oc"] as const;

/** Workbook Engine column → engine result accessor. */
const COLUMNS: Record<string, (r: RoundResult) => number | string> = {
  M: (r) => r.availableCapital,
  N: (r) => r.availableLc,
  T: (r) => r.initiativeCount,
  U: (r) => r.capitalCommitted,
  V: (r) => r.lcCommitted,
  W: (r) => r.unusedCapital,
  X: (r) => r.executionFactor,
  Y: (r) => r.changeFactor,
  CF: (r) => r.absorptionFactor,
  CD: (r) => r.lcReserve,
  CE: (r) => r.lcUtilization,
  CG: (r) => r.responseReserve,
  CT: (r) => r.repeatFactors[0],
  CU: (r) => r.repeatFactors[1],
  CV: (r) => r.repeatFactors[2],
  CW: (r) => r.repeatFactors[3],
  AY: (r) => r.events.m.total,
  BA: (r) => r.events.k.total,
  BB: (r) => r.events.f.total,
  BC: (r) => r.events.c.total,
  BF: (r) => r.events.marginPp.total,
  BH: (r) => r.events.winPp,
  BI: (r) => r.events.pricePp.total,
  CL: (r) => r.ocToC,
  BR: (r) => r.growth,
  BS: (r) => r.revenue,
  BT: (r) => r.margin,
  BU: (r) => r.mix,
  BV: (r) => r.nextCapital,
  BW: (r) => r.cashScore,
  BX: (r) => r.capabilityLoop,
  BY: (r) => r.rawHealth,
  BZ: (r) => r.pipeline,
  CA: (r) => r.winRate,
  CB: (r) => r.priceRealization,
  CC: (r) => r.status,
  CH: (r) => r.commercialGrowthPotential,
  CI: (r) => r.winFactor,
  CJ: (r) => r.priceFactor,
  CK: (r) => r.deliveryConstraint,
  DG: (r) => r.terminal.state.m,
  DH: (r) => r.terminal.state.v,
  DI: (r) => r.terminal.state.k,
  DJ: (r) => r.terminal.state.f,
  DK: (r) => r.terminal.state.c,
  DL: (r) => r.terminal.capabilityLoop,
  DM: (r) => r.terminal.rawHealth,
  DN: (r) => r.finalRawHealth,
  DO: (r) => r.systemHealth,
};
["Z", "AA", "AB", "AC", "AD", "AE", "AF", "AG", "AH"].forEach((col, i) => (COLUMNS[col] = (r) => r.immediate[EFFECT[i]]));
["AI", "AJ", "AK", "AL", "AM", "AN", "AO", "AP", "AQ"].forEach((col, i) => (COLUMNS[col] = (r) => r.lagged[EFFECT[i]]));
["CX", "CY", "CZ", "DA", "DB", "DC", "DD", "DE", "DF"].forEach((col, i) => (COLUMNS[col] = (r) => r.terminal.nextLagged[EFFECT[i]]));
["BK", "BL", "BM", "BN", "BO", "BP", "BQ"].forEach((col, i) => (COLUMNS[col] = (r) => r.out[LOOPS[i]]));
["CM", "CN", "CO", "CP", "CQ", "CR", "CS"].forEach((col, i) => (COLUMNS[col] = (r) => r.readiness[LOOPS[i]]));

const teams = golden.teams as unknown as { name: string; decisions: FixtureRound[]; engine: Record<string, number | string>[] }[];

describe.each(teams.map((t, i) => [`Team ${i + 1}: ${t.name}`, t] as const))("%s", (_label, team) => {
  const results = simulateTeam(defaultConfig, team.decisions.map(toDecisions));

  it.each([1, 2, 3, 4])("round %i matches every workbook Engine column", (round) => {
    const expected = team.engine[round - 1];
    const actual = results[round - 1];
    for (const [col, get] of Object.entries(COLUMNS)) {
      const want = expected[col];
      const got = get(actual);
      if (typeof want === "string") {
        expect(got, `column ${col}`).toBe(want);
      } else {
        expect(got as number, `column ${col}`).toBeCloseTo(want, D);
      }
    }
  });
});

describe("decision validation", () => {
  const base = {
    prev: {
      m: defaultConfig.base.m,
      v: defaultConfig.base.v,
      k: defaultConfig.base.k,
      f: defaultConfig.base.f,
      c: defaultConfig.base.c,
      ec: defaultConfig.base.ec,
      oc: defaultConfig.base.oc,
      revenue: defaultConfig.base.revenue,
      margin: defaultConfig.base.margin,
      mix: defaultConfig.base.mix,
    },
    availableCapital: 100,
    prior: null,
  };

  it("flags intensity mismatch", () => {
    const d = emptyDecisions();
    d.initiatives[0] = { name: "Run broad demand campaign", intensity: "None" };
    expect(computeRound(defaultConfig, { round: 1, decisions: d, ...base }).status).toBe("CHECK INTENSITY");
  });

  it("flags duplicate initiatives", () => {
    const d = emptyDecisions();
    d.initiatives[0] = { name: "Run broad demand campaign", intensity: "Focused" };
    d.initiatives[1] = { name: "Run broad demand campaign", intensity: "Accelerated" };
    expect(computeRound(defaultConfig, { round: 1, decisions: d, ...base }).status).toBe("DUPLICATE INITIATIVE");
  });

  it("flags over capital", () => {
    const d = emptyDecisions();
    d.initiatives[0] = { name: "Hire scarce advisory/AI talent", intensity: "Accelerated" }; // 40
    d.initiatives[1] = { name: "Form strategic AI partnership", intensity: "Accelerated" }; // 45
    d.initiatives[2] = { name: "Launch AI-enabled client offering", intensity: "Accelerated" }; // 45
    expect(computeRound(defaultConfig, { round: 1, decisions: d, ...base }).status).toBe("OVER CAPITAL");
  });

  it("flags over leadership capacity", () => {
    const d = emptyDecisions();
    d.initiatives[0] = { name: "Redesign compensation and rewards", intensity: "Accelerated" }; // LC 6
    d.initiatives[1] = { name: "Launch AI-enabled client offering", intensity: "Focused" }; // LC 4
    d.initiatives[2] = { name: "Redesign fixed-fee/value bundles", intensity: "Focused" }; // LC 3
    expect(computeRound(defaultConfig, { round: 1, decisions: d, ...base }).status).toBe("OVER LEADERSHIP CAPACITY");
  });

  it("flags strategic option before round 4", () => {
    const d = emptyDecisions();
    d.strategicOption = "Acquisition";
    expect(computeRound(defaultConfig, { round: 2, decisions: d, ...base }).status).toBe("ROUND 4 OPTION USED EARLY");
  });

  it("counts the strategic option toward the four-initiative limit", () => {
    const d = emptyDecisions();
    d.initiatives[0] = { name: "Add enterprise cross-sell scorecard", intensity: "Focused" };
    d.initiatives[1] = { name: "Clarify enterprise decision rights", intensity: "Focused" };
    d.initiatives[2] = { name: "Redesign fixed-fee/value bundles", intensity: "Focused" };
    d.initiatives[3] = { name: "Reskill and redeploy current talent", intensity: "Focused" };
    d.strategicOption = "Round 4 Partnership";
    d.evidenceTriggerMet = "Yes";
    const result = computeRound(defaultConfig, { round: 4, decisions: d, ...base });
    expect(result.initiativeCount).toBe(5);
    expect(result.status).toBe("TOO MANY INITIATIVES");
  });

  it("counts a named custom action toward the initiative limit", () => {
    const d = emptyDecisions();
    d.initiatives[0] = { name: "Add enterprise cross-sell scorecard", intensity: "Focused" };
    d.customAction = { name: "Pilot", capital: 0, lc: 0, m: 0, v: 0, k: 0, f: 0, c: 0, ec: 0, oc: 0, marginPp: 0, mixPp: 0 };
    expect(computeRound(defaultConfig, { round: 1, decisions: d, ...base }).initiativeCount).toBe(2);
  });

  it("requires a facilitator evidence review in round 4", () => {
    const d = emptyDecisions();
    expect(computeRound(defaultConfig, { round: 4, decisions: d, ...base }).status).toBe("EVIDENCE REVIEW REQUIRED");
    d.evidenceTriggerMet = "No";
    expect(computeRound(defaultConfig, { round: 4, decisions: d, ...base }).status).toBe("OK");
  });
});

describe("configurable departures from workbook parity", () => {
  it("applies workforce Control/OC lag in play only when enabled", () => {
    const decisions = [emptyDecisions(), emptyDecisions()];
    decisions[0].workforceReduction = true;
    const parity = simulateTeam(defaultConfig, decisions);
    const config = structuredClone(defaultConfig);
    config.workforceAction.applyControlOcLagInPlay = true;
    const applied = simulateTeam(config, decisions);
    expect(applied[1].lagged.c).toBe(parity[1].lagged.c + config.workforceAction.lagC);
    expect(applied[1].lagged.oc).toBe(parity[1].lagged.oc + config.workforceAction.lagOc);
  });
});
